#include <stdio.h>

char* encode(int num) {
    static char result[64];
    int len = 0;

    while (num > 0) {
        result[len++] = (num % 2 == 1) ? '0' : '1';
        num = (num - 1) / 2;
    }

    for (int i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = result[i];
        result[i] = result[j];
        result[j] = tmp;
    }
    result[len] = '\0';
    return result;
}

int main(void) {
    int num;
    if (scanf(" [%d]", &num) == 1) {
        printf("\"%s\"\n", encode(num));
    }
    return 0;
}

